//! `SyntheticPlatformer`: free, deterministic side-scroller fixture for CI.
//!
//! This is a synthetic fixture, NOT Mario: a minimal original level made of
//! ground, gaps, walls and spikes, generated by code. No asset or data from
//! any commercial game is used. Integer physics only, so runs are bit-exact.

use crate::port::{EmulatorPort, MarioFeatures, PadState, PortError, StepReport};

/// Label that every report involving the fixture must carry.
pub const SYNTHETIC_LABEL: &str = "synthetic fixture, not Mario";

const GOAL_X: i32 = 380;
/// Hazard layout (public so a mock coach can describe the level; spans are `[start, end)` in x).
pub const GAPS: [(i32, i32); 3] = [(60, 72), (150, 162), (260, 272)];
pub const WALLS: [(i32, i32); 3] = [(100, 108), (210, 218), (320, 328)];
const WALL_H: i32 = 16;
pub const SPIKES: [(i32, i32); 1] = [(180, 184)];
const SPIKE_H: i32 = 6;
const JUMP_VY: i32 = 7;
const MAX_FALL: i32 = -8;
const FALL_DEATH_Y: i32 = -30;
const START_LIVES: u8 = 3;
const MAX_FRAMES: u64 = 3_000;
const SNAP_MAGIC: &[u8; 4] = b"SPF1";
const RAM_LEN: usize = 24;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct State {
    x: i32,
    y: i32,
    vy: i32,
    on_ground: bool,
    lives: u8,
    deaths: u32,
    died: bool,
    complete: bool,
    game_over: bool,
    frame: u64,
}

impl State {
    const fn start() -> Self {
        Self {
            x: 0,
            y: 0,
            vy: 0,
            on_ground: true,
            lives: START_LIVES,
            deaths: 0,
            died: false,
            complete: false,
            game_over: false,
            frame: 0,
        }
    }
}

fn within(spans: &[(i32, i32)], x: i32) -> bool {
    spans.iter().any(|&(a, b)| x >= a && x < b)
}

/// Height of the floor under `x`, `None` over a gap.
fn support(x: i32) -> Option<i32> {
    if within(&GAPS, x) {
        None
    } else if within(&WALLS, x) {
        Some(WALL_H)
    } else {
        Some(0)
    }
}

/// Deterministic synthetic side-scroller implementing [`EmulatorPort`].
#[derive(Debug, Clone)]
pub struct SyntheticPlatformer {
    s: State,
    ram: [u8; RAM_LEN],
}

impl Default for SyntheticPlatformer {
    fn default() -> Self {
        Self::new()
    }
}

impl SyntheticPlatformer {
    pub fn new() -> Self {
        let mut p = Self {
            s: State::start(),
            ram: [0; RAM_LEN],
        };
        p.sync_ram();
        p
    }

    /// RAM layout: 0..4 x (i32 LE), 4..8 y, 8..12 vy, 12 on_ground, 13 lives,
    /// 14..18 deaths, 18 flags (bit0 died, bit1 complete, bit2 game_over),
    /// 19 reserved, 20..24 frame (low 32 bits).
    fn sync_ram(&mut self) {
        let s = self.s;
        self.ram[0..4].copy_from_slice(&s.x.to_le_bytes());
        self.ram[4..8].copy_from_slice(&s.y.to_le_bytes());
        self.ram[8..12].copy_from_slice(&s.vy.to_le_bytes());
        self.ram[12] = u8::from(s.on_ground);
        self.ram[13] = s.lives;
        self.ram[14..18].copy_from_slice(&s.deaths.to_le_bytes());
        self.ram[18] = u8::from(s.died) | u8::from(s.complete) << 1 | u8::from(s.game_over) << 2;
        self.ram[20..24].copy_from_slice(&(s.frame as u32).to_le_bytes());
    }

    fn frame(&mut self, pad: PadState) {
        let s = &mut self.s;
        s.died = false;
        s.frame += 1;
        let vx = if pad.has(PadState::RIGHT) {
            if pad.has(PadState::RUN) { 3 } else { 2 }
        } else if pad.has(PadState::LEFT) {
            -1
        } else {
            0
        };
        let nx = (s.x + vx).max(0);
        // Solid floor blocks from the side while the player is below its top
        // (walls, and the pit edges when already falling in a gap).
        if !support(nx).is_some_and(|h| s.y < h) {
            s.x = nx;
        }
        if s.on_ground && support(s.x).is_none_or(|h| h < s.y) {
            s.on_ground = false;
            s.vy = 0;
        }
        if pad.has(PadState::JUMP) && s.on_ground {
            s.vy = JUMP_VY;
            s.on_ground = false;
        }
        if !s.on_ground {
            let prev = s.y;
            s.y += s.vy;
            s.vy = (s.vy - 1).max(MAX_FALL);
            if let Some(h) = support(s.x)
                && s.vy <= 0
                && s.y <= h
                && prev >= h
            {
                s.y = h;
                s.vy = 0;
                s.on_ground = true;
            }
        }
        let hit_spike = within(&SPIKES, s.x) && s.y < SPIKE_H;
        if s.y < FALL_DEATH_Y || hit_spike {
            s.deaths += 1;
            s.died = true;
            s.lives -= 1;
            let keep = (s.lives, s.deaths, s.frame);
            *s = State::start();
            (s.lives, s.deaths, s.frame) = keep;
            s.died = true;
            if s.lives == 0 {
                s.game_over = true;
            }
        } else if s.x >= GOAL_X {
            s.complete = true;
        }
        if s.frame >= MAX_FRAMES && !s.complete {
            s.game_over = true;
        }
    }
}

impl EmulatorPort for SyntheticPlatformer {
    fn backend_name(&self) -> &'static str {
        "synthetic-fixture"
    }
    fn is_synthetic(&self) -> bool {
        true
    }
    fn reset(&mut self) {
        self.s = State::start();
        self.sync_ram();
    }
    fn step(&mut self, pad: PadState, frames: u32) -> StepReport {
        let mut run = 0;
        for _ in 0..frames {
            if self.s.complete || self.s.game_over {
                break;
            }
            self.frame(pad);
            run += 1;
        }
        self.sync_ram();
        StepReport {
            frames_run: run,
            features: self.features(),
        }
    }
    fn features(&self) -> MarioFeatures {
        let s = self.s;
        MarioFeatures {
            x: s.x,
            y: s.y,
            vy: s.vy,
            on_ground: s.on_ground,
            lives: s.lives,
            deaths: s.deaths,
            died_this_step: s.died,
            level_complete: s.complete,
            game_over: s.game_over,
            frame: s.frame,
        }
    }
    fn ram(&self) -> &[u8] {
        &self.ram
    }
    fn snapshot(&self) -> Result<Vec<u8>, PortError> {
        let mut v = SNAP_MAGIC.to_vec();
        v.extend_from_slice(&self.ram);
        v.extend_from_slice(&self.s.frame.to_le_bytes());
        Ok(v)
    }
    fn restore(&mut self, data: &[u8]) -> Result<(), PortError> {
        if data.len() != 4 + RAM_LEN + 8 {
            return Err(PortError::BadSnapshot("length"));
        }
        if &data[..4] != SNAP_MAGIC {
            return Err(PortError::BadSnapshot("magic"));
        }
        let r = &data[4..4 + RAM_LEN];
        let i32_at = |o: usize| i32::from_le_bytes(r[o..o + 4].try_into().unwrap());
        let flags = r[18];
        let lives = r[13];
        if r[12] > 1 || lives > START_LIVES || flags > 7 {
            return Err(PortError::BadSnapshot("field range"));
        }
        let frame = u64::from_le_bytes(data[4 + RAM_LEN..].try_into().unwrap());
        self.s = State {
            x: i32_at(0),
            y: i32_at(4),
            vy: i32_at(8),
            on_ground: r[12] == 1,
            lives,
            deaths: u32::from_le_bytes(r[14..18].try_into().unwrap()),
            died: flags & 1 != 0,
            complete: flags & 2 != 0,
            game_over: flags & 4 != 0,
            frame,
        };
        self.sync_ram();
        Ok(())
    }
}
